# =============================================================================
# Filesync Provider Integration Test
# =============================================================================
# Tests the terraform-provider-filesync against a real LXC container.

terraform {
  required_providers {
    filesync = {
      source  = "registry.terraform.io/darshan-rambhia/filesync"
      version = "0.1.0"
    }
  }
}

provider "filesync" {
  ssh_user     = "root"
  ssh_key_path = "~/.ssh/homelab_ed25519"
}

# Test 1: Simple text file
resource "filesync_file" "test_config" {
  source      = "${path.module}/files/test-config.txt"
  destination = "/etc/filesync-test/config.txt"
  host        = "192.168.1.206"

  owner = "root"
  group = "root"
  mode  = "0644"
}

# Test 2: File with restricted permissions
resource "filesync_file" "test_secret" {
  source      = "${path.module}/files/secret.txt"
  destination = "/etc/filesync-test/secret.txt"
  host        = "192.168.1.206"

  owner = "root"
  group = "root"
  mode  = "0600"
}

# Test 3: Nested directory path
resource "filesync_file" "test_nested" {
  source      = "${path.module}/files/nested-config.json"
  destination = "/etc/filesync-test/nested/deep/config.json"
  host        = "192.168.1.206"

  mode = "0644"
}

# Test 4: Directory sync
resource "filesync_directory" "test_config_dir" {
  source      = "${path.module}/files/config-dir"
  destination = "/etc/filesync-test/config-dir"
  host        = "192.168.1.206"

  owner = "root"
  group = "root"
  mode  = "0644"

  # Exclude sensitive files and git metadata
  exclude = ["*.key", ".gitignore"]
}

# Outputs for verification
output "config_hash" {
  value = filesync_file.test_config.source_hash
}

output "secret_hash" {
  value = filesync_file.test_secret.source_hash
}

output "nested_hash" {
  value = filesync_file.test_nested.source_hash
}

output "config_size" {
  value = filesync_file.test_config.size
}

output "dir_file_count" {
  value = filesync_directory.test_config_dir.file_count
}

output "dir_total_size" {
  value = filesync_directory.test_config_dir.total_size
}

output "dir_source_hash" {
  value = filesync_directory.test_config_dir.source_hash
}

