# =============================================================================
# Required Variables
# =============================================================================

variable "source_dir" {
  description = "Local directory to sync from"
  type        = string
}

variable "target_host" {
  description = "Target host IP or hostname"
  type        = string
}

variable "target_path" {
  description = "Target path on remote host"
  type        = string
}

variable "ssh_private_key_path" {
  description = "Path to SSH private key for authentication"
  type        = string
}

# =============================================================================
# Optional Variables
# =============================================================================

variable "owner" {
  description = "Owner to set on synced files (e.g., 'traefik')"
  type        = string
  default     = ""
}

variable "group" {
  description = "Group to set on synced files (e.g., 'traefik')"
  type        = string
  default     = ""
}

variable "file_permissions" {
  description = "Map of file paths to chmod permissions (e.g., { '/config/.env' = '600' })"
  type        = map(string)
  default     = {}
}

variable "delete_extra" {
  description = "Delete files on target that don't exist in source (rsync --delete)"
  type        = bool
  default     = true
}

variable "post_sync_commands" {
  description = "Additional commands to run after sync (e.g., restart services)"
  type        = list(string)
  default     = []
}

variable "depends_on_resources" {
  description = "List of resources this sync depends on"
  type        = list(any)
  default     = []
}

