# =============================================================================
# Cloudflare Tunnel Module - Variables
# =============================================================================

# -----------------------------------------------------------------------------
# Required Variables
# -----------------------------------------------------------------------------

variable "hostname" {
  description = "Hostname (subdomain) for the tunnel (e.g., 'n8n' becomes n8n.rambtech.dev)"
  type        = string
}

variable "domain" {
  description = "Root domain (e.g., 'rambtech.dev')"
  type        = string
}

variable "backend_url" {
  description = "Backend URL the tunnel routes to (usually Traefik: http://192.168.1.162)"
  type        = string
}

variable "tunnel_id" {
  description = "Cloudflare tunnel ID"
  type        = string
}

# -----------------------------------------------------------------------------
# Optional Variables
# -----------------------------------------------------------------------------

variable "app_name" {
  description = "App name for DNS record comment"
  type        = string
  default     = ""
}

variable "cloudflare_account_id" {
  description = "Cloudflare account ID (required if managing ingress via API)"
  type        = string
  default     = ""
}

variable "manage_ingress" {
  description = "Manage tunnel ingress rules via API (false = use local config file)"
  type        = bool
  default     = false
}

# -----------------------------------------------------------------------------
# Tunnel Configuration Options (used if manage_ingress = true)
# -----------------------------------------------------------------------------

variable "connect_timeout" {
  description = "Timeout for establishing connection to origin"
  type        = string
  default     = "30s"
}

variable "tls_timeout" {
  description = "Timeout for TLS handshake with origin"
  type        = string
  default     = "10s"
}

variable "tcp_keep_alive" {
  description = "TCP keepalive interval"
  type        = string
  default     = "30s"
}

variable "no_happy_eyeballs" {
  description = "Disable happy eyeballs (IPv4/IPv6 fallback)"
  type        = bool
  default     = false
}

variable "keep_alive_connections" {
  description = "Maximum keepalive connections"
  type        = number
  default     = 100
}

variable "keep_alive_timeout" {
  description = "Keepalive timeout"
  type        = string
  default     = "1m30s"
}

variable "http_host_header" {
  description = "Override HTTP Host header sent to origin"
  type        = string
  default     = ""
}

variable "origin_server_name" {
  description = "Server name for origin TLS verification"
  type        = string
  default     = ""
}

variable "disable_chunked_encoding" {
  description = "Disable chunked transfer encoding"
  type        = bool
  default     = false
}

