terraform {
  required_providers {
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

locals {
  # Build the notes content
  notes_content = templatefile("${path.module}/templates/notes.md.tftpl", {
    service_name = var.service_name
    description  = var.description
    urls         = var.urls
    services     = var.services
    ssh_host     = var.ssh_host
    custom_notes = var.custom_notes
    managed_by   = var.managed_by
    timestamp    = timestamp()
  })

  # Escape single quotes for shell
  escaped_notes = replace(local.notes_content, "'", "'\\''")
}

resource "null_resource" "update_notes" {
  triggers = {
    notes_hash   = md5(local.notes_content)
    container_id = var.container_id
  }

  provisioner "local-exec" {
    command = <<-EOT
      ssh -i ${var.ssh_private_key_path} \
        -o StrictHostKeyChecking=no \
        root@${var.proxmox_host} \
        "pct set ${var.container_id} -description '${local.escaped_notes}'"
    EOT
  }
}

# =============================================================================
# Required Variables
# =============================================================================

variable "name" {
  description = "Name/hostname of the LXC container"
  type        = string
}

variable "container_id" {
  description = "Proxmox container ID (VMID)"
  type        = number
}

# =============================================================================
# Proxmox Connection
# =============================================================================

variable "proxmox_node" {
  description = "Proxmox node to create the container on"
  type        = string
}

variable "ssh_public_key" {
  description = "SSH public key content for root access"
  type        = string
}

# =============================================================================
# Compute Resources
# =============================================================================

variable "cores" {
  description = "Number of CPU cores"
  type        = number
  default     = 1
}

variable "memory" {
  description = "Memory in MB"
  type        = number
  default     = 512
}

variable "swap" {
  description = "Swap in MB"
  type        = number
  default     = 512
}

variable "description" {
  description = "Container description (supports markdown)"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags for the container"
  type        = list(string)
  default     = []

